-- Jeu de LecteurRapprochementActeurs / EcrivainRapprochementActeurs (« Rapprocher des acteurs », PROC_RAPPACTEUR), lot 14 du
-- plan-676a4b19. Identifiants 24001xx (mandataires) et 24009xx (liaisons). Ce qui est retenu ou ecarte, et pourquoi :
-- PROC_RAPPACTEUR.attendu et .gestes.
-- Les tables, aux types de RIG_DEV (classes RigBaseGreffe\GREFFE\<TABLE>.cs, « Champs ... de type ... dans la BD ») : seulement les
-- colonnes lues ou ecrites. Ce jeu est joue APRES PROC_CHM, PROC_MANDATAIRE, PROC_MODIF_REPER et PROC_ORDOSIGN, qui creent JUGE,
-- MANDATAIRE_PC, MANDATAIRE, REPERTORIE et VIDIGED_INDEX : il ne fait que leur ajouter les colonnes qui manquent (nullables, ou a
-- DEFAULT), et cree les tables de liaison qu'aucun autre jeu ne cree (CREANCIER_PC, CREANCE_TRANSITOIRE, DEMAT_CFEC_AJMJ_VIDIGED,
-- ACTEUR_SUPP). Les lignes passent par sp_executesql (une colonne ajoutee ici n'est pas connue a la compilation du lot).
IF COL_LENGTH('v2.JUGE', 'JUG_ABREGE') IS NULL ALTER TABLE v2.JUGE ADD JUG_ABREGE varchar(16) NULL;
IF COL_LENGTH('v2.JUGE', 'JUG_ACTIF') IS NULL ALTER TABLE v2.JUGE ADD JUG_ACTIF bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_ABREGE') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_ABREGE varchar(16) NULL;
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_COMPLEMENT_NOM') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_COMPLEMENT_NOM varchar(100) NULL;
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_ACTIF') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_ACTIF bit NOT NULL DEFAULT (1);
-- Les liaisons d'un mandataire (Mandataire.GetLiaisonEntite, LiaisonsMandataire.cs).
-- CREANCIER_PC et CREANCE_TRANSITOIRE : PROC_ADDCREANCE.sql (lot 12), joue avant, les cree aussi, avec leurs colonnes NOT NULL de
-- RIG_DEV (CREPC_SUBROGE, CRTRA_DATE_CREATION) : ce jeu les cree de meme et les remplit (reunion des lots 12 et 14, 27/11/2026).
IF OBJECT_ID(N'v2.CREANCIER_PC') IS NULL
    CREATE TABLE v2.CREANCIER_PC (CREPC_ID_CREPC int NOT NULL PRIMARY KEY, CREPC_SUBROGE bit NOT NULL, CREPC_ID_MNDTR int NULL);
IF COL_LENGTH('v2.CREANCIER_PC', 'CREPC_ID_MNDTR') IS NULL ALTER TABLE v2.CREANCIER_PC ADD CREPC_ID_MNDTR int NULL;
IF OBJECT_ID(N'v2.CREANCE_TRANSITOIRE') IS NULL
    CREATE TABLE v2.CREANCE_TRANSITOIRE (CRTRA_ID_CRTRA int NOT NULL PRIMARY KEY, CRTRA_DATE_CREATION datetime NOT NULL,
        CRTRA_DATE_INSERTION_RIG datetime NULL, CRTRA_ID_MNDTR int NULL);
IF COL_LENGTH('v2.CREANCE_TRANSITOIRE', 'CRTRA_ID_MNDTR') IS NULL ALTER TABLE v2.CREANCE_TRANSITOIRE ADD CRTRA_ID_MNDTR int NULL;
IF OBJECT_ID(N'v2.DEMAT_CFEC_AJMJ_VIDIGED') IS NULL
    CREATE TABLE v2.DEMAT_CFEC_AJMJ_VIDIGED (CFECAJV_ID_CFECAJV int NOT NULL PRIMARY KEY, CFECAJV_TYPE_DEPOSANT varchar(50) NULL,
        CFECAJV_ID_DEPOSANT int NULL);
IF OBJECT_ID(N'v2.REPERTORIE') IS NULL
    CREATE TABLE v2.REPERTORIE (PRTRP_ID_PRTRP int NOT NULL PRIMARY KEY, PRTRP_ID_MNDTR_POS int NULL);
IF OBJECT_ID(N'v2.VIDIGED_INDEX') IS NULL
    CREATE TABLE v2.VIDIGED_INDEX (VGIDX_ID_VGIDX int NOT NULL PRIMARY KEY);
IF COL_LENGTH('v2.VIDIGED_INDEX', 'VGIDX_TYPE_DEPOSANT') IS NULL ALTER TABLE v2.VIDIGED_INDEX ADD VGIDX_TYPE_DEPOSANT varchar(50) NULL;
IF COL_LENGTH('v2.VIDIGED_INDEX', 'VGIDX_ID_DEPOSANT') IS NULL ALTER TABLE v2.VIDIGED_INDEX ADD VGIDX_ID_DEPOSANT int NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_DEPOSANT_GED varchar(50) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_ID_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_ID_DEPOSANT_GED int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_TYPE_DEPOSANT_GED varchar(50) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_DEPOSANT_GED') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_DEPOSANT_GED int NULL;
-- La piste d'audit de la fusion (ACTEUR_SUPP.cs : toutes ses colonnes).
IF OBJECT_ID(N'v2.ACTEUR_SUPP') IS NULL
    CREATE TABLE v2.ACTEUR_SUPP (ACTSUP_ID_ACTSUP int NOT NULL PRIMARY KEY, ACTSUP_TABLE_SUPP varchar(128) NOT NULL, ACTSUP_ID_SUPP int NOT NULL,
        ACTSUP_ID_REMPL int NOT NULL, ACTSUP_REQUETE varchar(max) NOT NULL, ACTSUP_DATE_CREATION datetime NULL, ACTSUP_AUTEUR varchar(128) NULL,
        ACTSUP_SUPP_DESIGNATION varchar(200) NULL, ACTSUP_REMPL_DESIGNATION varchar(200) NULL);

EXEC sp_executesql N'
INSERT INTO v2.MANDATAIRE (MNDTR_ID_MNDTR, MNDTR_CIVILITE, MNDTR_NOM, MNDTR_ABREGE, MNDTR_NUMERO_CNBF, MNDTR_ACTIF) VALUES
    -- le mandataire a GARDER : actif et repertorie (le filtre « ACTIF » de la liste a garder, .Mandataires.cs:166-176)
    (2400101, ''ME'', ''DOUBLON Garde'', ''DBG24'', NULL, 1),
    -- son DOUBLON, sans abrege : trois liaisons (ci-dessous), reprises par la fusion puis supprime
    (2400102, ''ME'', ''DOUBLON Garde'', NULL, NULL, 1),
    -- actif a numero CNBF : la V2 refuse de le supprimer (Res.cs:35) -- sa ligne est « Protégé » (Validee, figee)
    (2400103, ''MR'', ''CNBF Actif'', NULL, ''240001'', 1),
    -- INACTIF : ne peut pas etre garde (la V2 ne propose que les actifs a garder) -- jumeau accepte : 2400101
    (2400104, ''MR'', ''INACTIF Garde'', NULL, NULL, 0);
-- la creance transitoire est deja integree (date d''insertion dans RIG) : elle n''entre pas dans « Intégrer des créances » (lot 12)
INSERT INTO v2.CREANCE_TRANSITOIRE (CRTRA_ID_CRTRA, CRTRA_DATE_CREATION, CRTRA_DATE_INSERTION_RIG, CRTRA_ID_MNDTR) VALUES (2400901, ''20000101'', ''20000102'', 2400102);
INSERT INTO v2.CREANCIER_PC (CREPC_ID_CREPC, CREPC_SUBROGE, CREPC_ID_MNDTR) VALUES (2400911, 0, 2400102);
-- deux depots demat : l''un depose par le doublon (MANDATAIRE 2400102), l''autre par un MANDATAIRE_PC de meme numero -- le type
-- distingue (jumeau ecarte : 2400922 n''est pas repris)
INSERT INTO v2.DEMAT_CFEC_AJMJ_VIDIGED (CFECAJV_ID_CFECAJV, CFECAJV_TYPE_DEPOSANT, CFECAJV_ID_DEPOSANT) VALUES
    (2400921, ''MANDATAIRE'', 2400102), (2400922, ''MANDATAIRE_PC'', 2400102);';

-- La fusion des JUGES et des MANDATAIRES PC (_DeleteJuges, _DeleteMandatairesPC). Identifiants 24002xx (juges), 24003xx (mandataires PC),
-- 24008xx (leurs liaisons), 24008 8x (destinataires d'edition). Les liaisons visent une PC et une instance qui n'existent pas (2400891,
-- 2400892, 2400899) : aucun autre ecran, qui part des PC ou des instances, ne voit ces lignes. Tables creees ici avec la definition des
-- jeux joues apres (INSTANCE_JUGE et DEMAT_CFEC : PROC_SUPP_ACTEUR_JUD.sql ; DESTINATAIRES_EDITIONS_LOT2 : PROC_XXAFF.sql), plus les
-- colonnes que _SaveEdiLot2 lit (DESTINATAIRES_EDITIONS_LOT2.cs de RigBaseGreffe : DESED_ID_PRCLL, DESED_ID_PREVE int NULL,
-- DESED_XML_DESTEDIT varchar(max) NULL).
IF OBJECT_ID(N'v2.INSTANCE_JUGE') IS NULL
    CREATE TABLE v2.INSTANCE_JUGE (JUGIN_ID_JUGIN int NOT NULL PRIMARY KEY, JUGIN_ID_INSTN int NOT NULL);
IF COL_LENGTH('v2.INSTANCE_JUGE', 'JUGIN_ID_JUG') IS NULL ALTER TABLE v2.INSTANCE_JUGE ADD JUGIN_ID_JUG int NULL;
IF OBJECT_ID(N'v2.DEMAT_CFEC') IS NULL
    CREATE TABLE v2.DEMAT_CFEC (CFEC_ID_CFEC int NOT NULL PRIMARY KEY, CFEC_ID_MANDATAIRE_PC int NULL);
IF OBJECT_ID(N'v2.DESTINATAIRES_EDITIONS_LOT2') IS NULL
    CREATE TABLE v2.DESTINATAIRES_EDITIONS_LOT2 (DESED_ID_DESED int NOT NULL PRIMARY KEY, DESED_ID_INSTN int NULL);
IF COL_LENGTH('v2.DESTINATAIRES_EDITIONS_LOT2', 'DESED_ID_PRCLL') IS NULL ALTER TABLE v2.DESTINATAIRES_EDITIONS_LOT2 ADD DESED_ID_PRCLL int NULL;
IF COL_LENGTH('v2.DESTINATAIRES_EDITIONS_LOT2', 'DESED_ID_PREVE') IS NULL ALTER TABLE v2.DESTINATAIRES_EDITIONS_LOT2 ADD DESED_ID_PREVE int NULL;
IF COL_LENGTH('v2.DESTINATAIRES_EDITIONS_LOT2', 'DESED_XML_DESTEDIT') IS NULL ALTER TABLE v2.DESTINATAIRES_EDITIONS_LOT2 ADD DESED_XML_DESTEDIT varchar(max) NULL;
-- Le juge par defaut des injonctions (PARAMETRAGE IP_JUGE, repris dans soc.Reglage) : le juge 2400203, que la fusion refuse de supprimer.
IF NOT EXISTS (SELECT 1 FROM soc.Reglage WHERE Code = 'IP_JUGE')
    INSERT INTO soc.Reglage (Code, Libelle, Valeur) VALUES ('IP_JUGE', 'Banc EcransGeneresBase lot 14', '2400203');

EXEC sp_executesql N'
INSERT INTO v2.JUGE (JUG_ID_JUG, JUG_ABREGE, JUG_CIVILITE, JUG_NOM, JUG_PRENOM, JUG_ACTIF) VALUES
    -- le juge a GARDER, repertorie (abrege J14G)
    (2400201, ''J14G'', ''MME'', ''FUSIONJUGE'', ''Rose'', 1),
    -- son DOUBLON, sans abrege : trois liaisons et une PC dont il est juge-commissaire, reprises par la fusion puis supprime
    (2400202, NULL, ''MME'', ''FUSIONJUGE'', ''Rose'', 1),
    -- le juge par defaut des injonctions (IP_JUGE) : ne se supprime pas (Res.TEXTE_JUGE_EN_PARAM_IP) -- jumeau accepte : 2400202
    (2400203, ''J14P'', ''MR'', ''FUSIONIP'', ''Paul'', 1),
    -- sans abrege : ne peut pas etre garde (la liste « a garder » de la V2 exige l''abrege) -- jumeau accepte : 2400201
    (2400204, NULL, ''MR'', ''FUSIONSANS'', ''Abel'', 1);
INSERT INTO v2.INSTANCE_JUGE (JUGIN_ID_JUGIN, JUGIN_ID_INSTN, JUGIN_ID_JUG) VALUES (2400801, 2400899, 2400202);
INSERT INTO v2.ETRE_JUGE_COMM (ETJCM_ID_ETJCM, ETJCM_ID_JUG, ETJCM_ID_PRCLL, ETJCM_FONCTION_PC, ETJCM_FIN_MISSION) VALUES (2400802, 2400202, 2400891, ''JC'', 0);
INSERT INTO v2.MANDATAIRE_PC (MNDPC_ID_MNDPC, MNDPC_CIVILITE, MNDPC_NOM, MNDPC_COMPLEMENT_NOM, MNDPC_ABREGE, MNDPC_ACTIF) VALUES
    -- le mandataire PC a GARDER (abrege M14G) et son DOUBLON sans abrege
    (2400301, ''ME'', ''FUSIONPC'', ''Selarl'', ''M14G'', 1), (2400302, ''ME'', ''FUSIONPC'', ''Selarl'', NULL, 1);
INSERT INTO v2.GERER_PC (GRRPC_ID_GRRPC, GRRPC_ID_MNDPC, GRRPC_ID_PRCLL, GRRPC_NUM_ORDRE, GRRPC_FONCTION_PC, GRRPC_FIN_MISSION) VALUES
