INSERT INTO v2.DEMAT_CFEC (CFEC_ID_CFEC, CFEC_ID_MANDATAIRE_PC) VALUES (2400806, 2400302);
-- les coffres recus : deposes par le juge doublon (JUGE) et par le mandataire PC doublon (ADMINISTRATEUR) ; jumeaux ecartes, de meme
-- numero mais d''un autre type : 2400804 (MANDATAIRE 2400202, pas un juge) et 2400808 (JUGE 2400302, pas un mandataire PC)
