    (2400881, 2400891, ''<LISTE_ENTITES><ENTITE CODE="JUGE" VALEUR="2400202" /><ENTITE CODE="MANDATAIRE_PC" VALEUR="2400202" /></LISTE_ENTITES>''),
    (2400882, 2400892, ''<LISTE_ENTITES><ENTITE CODE="MANDATAIRE_PC" VALEUR="2400302" /><ENTITE CODE="JUGE" VALEUR="2400302" /></LISTE_ENTITES>'');';

-- Pour PROC_GESTTIERSPAYEURS (joue avant PROC_JVENTE, qui cree FACTURE) : la colonne du payeur d'une facture, que la suppression d'un
-- tiers payeur lit (Facture.GetFactureByIdPayeur ; FACTURE.cs de RigBaseGreffe : FACTU_ID_PYEUR int NULL).
IF OBJECT_ID(N'v2.FACTURE') IS NOT NULL AND COL_LENGTH('v2.FACTURE', 'FACTU_ID_PYEUR') IS NULL ALTER TABLE v2.FACTURE ADD FACTU_ID_PYEUR int NULL;
